CREATE TABLE public.categories (slug text PRIMARY KEY, name text NOT NULL, intro text NOT NULL DEFAULT '', position int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.brands (slug text PRIMARY KEY, name text NOT NULL, region text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.products (id text PRIMARY KEY, name text NOT NULL, brand_slug text NOT NULL REFERENCES public.brands(slug), category_slug text NOT NULL REFERENCES public.categories(slug), form text NOT NULL, price numeric(10,2) NOT NULL, rating numeric(2,1) NOT NULL DEFAULT 0, reviews int NOT NULL DEFAULT 0, image_key text NOT NULL, gallery_keys text[] NOT NULL DEFAULT '{}', tagline text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', composition text NOT NULL DEFAULT '', dosage text NOT NULL DEFAULT '', is_new boolean NOT NULL DEFAULT false, best_seller boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.categories, public.brands, public.products TO anon, authenticated;
GRANT ALL ON public.categories, public.brands, public.products TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.brands ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read categories" ON public.categories FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public read brands" ON public.brands FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public read products" ON public.products FOR SELECT TO anon, authenticated USING (true);
UPDATE public.products SET composition = tagline || '. Formule garantie sans stéarate de magnésium, sans dioxyde de titane, sans nanoparticules, sans lactose et sans gluten.', dosage = '2 prises par jour avec un verre d''eau, de préférence au cours du dîner. Cure recommandée de 30 à 90 jours consécutifs.' WHERE id IS NOT NULL;
UPDATE public.products SET composition = 'Bisglycinate de magnésium chélaté : 300 mg de magnésium élément (80% AR). Vitamine B6 bioactive (P-5-P) : 2 mg (142% AR). Enveloppe en pullulane d''origine naturelle. Sans stéarate de magnésium, sans dioxyde de titane, sans nanoparticules, sans lactose et sans gluten.', dosage = 'Prendre 2 gélules par jour avec un verre d''eau, de préférence au cours du dîner pour soutenir la détente musculaire nocturne. Cure de 30 à 90 jours, renouvelable en période de surmenage.' WHERE id = 'magnesium-bisglycinate';